;(function(){
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('[data-reveal]').forEach(e=>io.observe(e));
})();
;(function(){
/* details 의 name 속성(한 번에 하나만 열리는 아코디언)을 모르는 낡은 브라우저 보강.
   지원하는 브라우저에서는 바로 빠진다 — 이미 브라우저가 배타로 묶어 준다. */
(function(){
  if("name" in document.createElement("details")) return;
  var items=[].slice.call(document.querySelectorAll("details.g-item"));
  items.forEach(function(d){
    d.addEventListener("toggle",function(){
      if(!d.open) return;
      items.forEach(function(o){ if(o!==d) o.open=false; });
    });
  });
})();
})();
